	static SpreadGrass(
		i: number,
		j: number,
		dirt: number,
		grass: number,
		repeat: boolean,
		color: TileColorCache
	): void {
		try {
			if (
				!WorldGen.InWorld_Int32_Int32_Int32(i, j, 10) ||
				!Rt.tile.get(i, j).active_() ||
				Rt.tile.get(i, j).type !== dirt
			) {
				return;
			}
			if (WorldGen.isGeneratingOrLoadingWorld && (grass === 199 || grass === 23)) {
				let num: number = WorldGen.beachDistance;
				if (
					(!WorldGen.tenthAnniversaryWorldGen &&
						i > Main.maxTilesX * 0.45 &&
						i <= Main.maxTilesX * 0.55) ||
					i < num ||
					i >= ((Main.maxTilesX - num) | 0)
				) {
					return;
				}
			} else if (
				(WorldGen.isGeneratingOrLoadingWorld ||
					(grass !== 199 && grass !== 23 && grass !== 661 && grass !== 662)) &&
				(Rt.tile.get(i, j).type !== dirt ||
					!Rt.tile.get(i, j).active_() ||
					(j >= Main.worldSurface && dirt === 0)) &&
				!WorldGen.growGrassUnderground
			) {
				return;
			}
			let num2: number = (i - 1) | 0;
			let num3: number = (i + 2) | 0;
			let num4: number = (j - 1) | 0;
			let num5: number = (j + 2) | 0;
			if (num2 < 0) {
				num2 = 0;
			}
			if (num3 > Main.maxTilesX) {
				num3 = Main.maxTilesX;
			}
			if (num4 < 0) {
				num4 = 0;
			}
			if (num5 > Main.maxTilesY) {
				num5 = Main.maxTilesY;
			}
			let flag: boolean = true;
			for (let k: number = num2; k < num3; k++) {
				for (let l: number = num4; l < num5; l++) {
					if (!Rt.tile.get(k, l).active_() || !Main.tileSolid[Rt.tile.get(k, l).type]) {
						flag = false;
					}
					if (Rt.tile.get(k, l).lava_() && Rt.tile.get(k, l).liquid > 0) {
						flag = true;
						break;
					}
				}
			}
			if (
				flag ||
				!WorldGen.CanBeClearedDuringGeneration(Rt.tile.get(i, j).type, i, j, true) ||
				((grass === 23 || grass === 661) && Rt.tile.get(i, (j - 1) | 0).type === 27) ||
				((grass === 199 || grass === 662) && Rt.tile.get(i, (j - 1) | 0).type === 27) ||
				(grass === 109 && Rt.tile.get(i, (j - 1) | 0).type === 27)
			) {
				return;
			}
			let flag2: boolean = dirt > 0 && TileID_Sets_Conversion.Grass[dirt];
			let num6: boolean =
				grass === 23 ||
				grass === 661 ||
				grass === 199 ||
				grass === 662 ||
				grass === 109 ||
				grass === 492;
			if (flag2 && (grass === 23 || grass === 661)) {
				$hole('Terraria.WorldGen.Convert');
			} else if (flag2 && (grass === 199 || grass === 662)) {
				$hole('Terraria.WorldGen.Convert');
			} else if (flag2 && grass === 109) {
				$hole('Terraria.WorldGen.Convert');
			} else {
				WorldGen.TryConvertingOrKillingTreesAboveIfTheyWouldBecomeInvalid(i, j, grass);
				Rt.tile.get(i, j).type = grass & 0xffff;
				WorldGen.SquareTileFrame(i, j, true);
			}
			if (!!(!num6 || !$hole('Terraria.SpecialSeedFeatures.RainbowSandAndBlackSandWalls'))) {
				Rt.tile.get(i, j).UseBlockColors(color.clone());
			}
			NetMessage.SendTileSquare_Int32_Int32_Int32_Int32_TileChangeType(-1, i, j, 3, 0);
			for (let m: number = num2; m < num3; m++) {
				for (let n: number = num4; n < num5; n++) {
					if (!Rt.tile.get(m, n).active_() || Rt.tile.get(m, n).type !== dirt) {
						continue;
					}
					try {
						if (repeat && WorldGen.grassSpread < 1000) {
							WorldGen.grassSpread++;
							WorldGen.SpreadGrass(m, n, dirt, grass, true, new TileColorCache());
							WorldGen.grassSpread--;
						}
					} catch (__caught) {
						$caught(__caught);
					}
				}
			}
		} catch (__caught) {
			$caught(__caught);
		}
	}

	static digTunnel(
		X: number,
		Y: number,
		xDir: number,
		yDir: number,
		Steps: number,
		Size: number,
		Wet: boolean
	): Vector2D {
		let num: number = X;
		let num2: number = Y;
		try {
			let num3: number = 0;
			let num4: number = 0;
			let num5: number = Size;
			num = Utils.Clamp_T_T_T(num, num5 + 1, Main.maxTilesX - num5 - 1);
			num2 = Utils.Clamp_T_T_T(num2, num5 + 1, Main.maxTilesY - num5 - 1);
			for (let i: number = 0; i < Steps; i++) {
				for (let j: number = Math.trunc(num - num5) | 0; j <= num + num5; j++) {
					for (let k: number = Math.trunc(num2 - num5) | 0; k <= num2 + num5; k++) {
						if (
							Math.abs(j - num) + Math.abs(k - num2) <
								num5 * (1 + WorldGen.genRand.Next_Int32_Int32(-10, 11) * 0.005) &&
							j >= 0 &&
							j < Main.maxTilesX &&
							k >= 0 &&
							k < Main.maxTilesY
						) {
							Rt.tile.get(j, k).active_Boolean(false);
							if (Wet) {
								Rt.tile.get(j, k).liquid = 255;
								Rt.tile.get(j, k).liquidType_Int32(0);
							}
						}
					}
				}
				num5 += WorldGen.genRand.Next_Int32_Int32(-50, 51) * 0.03;
				if (num5 < Size * 0.6) {
					num5 = Size * 0.6;
				}
				if (num5 > Math.imul(Size, 2)) {
					num5 = Math.imul(Size, 2);
				}
				num3 += WorldGen.genRand.Next_Int32_Int32(-20, 21) * 0.01;
				num4 += WorldGen.genRand.Next_Int32_Int32(-20, 21) * 0.01;
				if (num3 < -1) {
					num3 = -1;
				}
				if (num3 > 1) {
					num3 = 1;
				}
				if (num4 < -1) {
					num4 = -1;
				}
				if (num4 > 1) {
					num4 = 1;
				}
				num += (xDir + num3) * 0.6;
				num2 += (yDir + num4) * 0.6;
			}
		} catch (__caught) {
			$caught(__caught);
		}
		return new Vector2D(num, num2);
	}

	static IsTreeType(tree: number): boolean {
		if (tree >= 0) {
			return TileID_Sets.IsATreeTrunk[tree];
		}
		return false;
	}

	static CanBeClearedDuringGeneration(
		tileType: number,
		x: number,
		y: number,
		skipDualDungeonCheck: boolean
	): boolean {
		if (
			WorldGen.isGeneratingOrLoadingWorld &&
			!skipDualDungeonCheck &&
			WorldGen_SecretSeed.dualDungeons.Enabled &&
			DungeonUtils.InAnyPotentialDungeonBounds(x, y) &&
			DungeonUtils.IsConsideredDungeonTile(tileType, true)
		) {
			return false;
		}
		return TileID_Sets.CanBeClearedDuringGeneration[tileType];
	}

	static GetWorldSize(): number {
		if (Main.maxTilesX <= 4200) {
			return 0;
		}
		if (Main.maxTilesX <= 6400) {
			return 1;
		}
		return 2;
	}

	static InWorld_Int32_Int32_Int32(x: number, y: number, fluff: number): boolean {
		if (
			x < fluff ||
			x >= ((Main.maxTilesX - fluff) | 0) ||
			y < fluff ||
			y >= ((Main.maxTilesY - fluff) | 0)
		) {
			return false;
		}
		return true;
	}

	static PlaceWall(i: number, j: number, type: number, mute: boolean): void {
		if (i <= 1 || j <= 1 || i >= ((Main.maxTilesX - 2) | 0) || j >= ((Main.maxTilesY - 2) | 0)) {
			return;
		}
		if (Rt.tile.get(i, j) === null) {
			Rt.tile.set(i, j, new Tile());
		}
		if (Rt.tile.get(i, j).wall === 0) {
			Rt.tile.get(i, j).wall = type & 0xffff;
			WorldGen.SquareWallFrame(i, j, true);
			if (!mute) {
				$sound(0, Math.imul(i, 16), Math.imul(j, 16), 1, 1, 0);
			}
		}
	}

	static SquareWallFrame(i: number, j: number, resetFrame: boolean): void {
		Framing.WallFrame((i - 1) | 0, (j - 1) | 0, false);
		Framing.WallFrame((i - 1) | 0, j, false);
		Framing.WallFrame((i - 1) | 0, (j + 1) | 0, false);
		Framing.WallFrame(i, (j - 1) | 0, false);
		Framing.WallFrame(i, j, resetFrame);
		Framing.WallFrame(i, (j + 1) | 0, false);
		Framing.WallFrame((i + 1) | 0, (j - 1) | 0, false);
		Framing.WallFrame((i + 1) | 0, j, false);
		Framing.WallFrame((i + 1) | 0, (j + 1) | 0, false);
	}

